import * as THREE from 'three';
import {bounceContact} from './contacts.js';
export function makeEffects(scene,support,settings,physics,getTrampolines=()=>[]){
 const bits=[],trails=[],dust=[],cache=new Map(),cube=new THREE.BoxGeometry(1,1,1),sphere=new THREE.IcosahedronGeometry(1,0),shard=new THREE.ConeGeometry(1,1,3),dustGeo=new THREE.SphereGeometry(1,8,6);
 const stainGeometry=new THREE.PlaneGeometry(1,1),stainBatches=new Map(),bloodDrops=[],bloodDummy=new THREE.Object3D();let stainCount=0;
 const bloodMaterials=Array.from({length:4},(_,i)=>{const map=new THREE.TextureLoader().load('assets/blood-'+(i+1)+'.webp');map.colorSpace=THREE.SRGBColorSpace;return new THREE.MeshStandardMaterial({map,transparent:true,opacity:.95,alphaTest:.025,roughness:.22,metalness:0,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-2,polygonOffsetUnits:-1});});
 const bloodSpray=new THREE.InstancedMesh(sphere,new THREE.MeshStandardMaterial({color:0xc2112d,roughness:.2}),256);bloodSpray.count=0;bloodSpray.frustumCulled=false;scene.add(bloodSpray);
 function stain(x,y,z,width,height=width,angle=Math.random()*Math.PI*2,variant=Math.floor(Math.random()*4)){
  let batch=stainBatches.get(variant);
  if(!batch||batch.count===batch.capacity){const capacity=batch?batch.capacity*2:128,mesh=new THREE.InstancedMesh(stainGeometry,bloodMaterials[variant],capacity);mesh.count=batch?.count||0;mesh.frustumCulled=false;mesh.receiveShadow=true;mesh.userData.blood=true;if(batch){for(let i=0;i<batch.count;i++){batch.mesh.getMatrixAt(i,bloodDummy.matrix);mesh.setMatrixAt(i,bloodDummy.matrix);}scene.remove(batch.mesh);batch.mesh.dispose();}batch={mesh,capacity,count:mesh.count};stainBatches.set(variant,batch);scene.add(mesh);}
  bloodDummy.position.set(x,y+.018+(stainCount%5)*.001,z);bloodDummy.rotation.set(-Math.PI/2,0,angle);bloodDummy.scale.set(width,height,1);bloodDummy.updateMatrix();batch.mesh.setMatrixAt(batch.count++,bloodDummy.matrix);batch.mesh.count=batch.count;batch.mesh.instanceMatrix.needsUpdate=true;stainCount++;
 }
 function updateBlood(dt){for(let i=bloodDrops.length-1;i>=0;i--){const drop=bloodDrops[i];drop.life-=dt;drop.velocity.y-=24*dt;const previous=drop.position.y;drop.position.addScaledVector(drop.velocity,dt);if(drop.position.y<=drop.floor+.025){drop.floor=support(drop.position.x,drop.position.z,previous);if(drop.position.y<=drop.floor+.025){stain(drop.position.x,drop.floor,drop.position.z,drop.size*5,.12+drop.size*3);bloodDrops.splice(i,1);continue;}}if(drop.life<=0){bloodDrops.splice(i,1);continue;}}
  // Compact surviving particles after removals; permanent stains use separate instanced batches.
  bloodDrops.forEach((drop,i)=>{bloodDummy.position.copy(drop.position);bloodDummy.rotation.set(0,0,0);bloodDummy.scale.set(drop.size,drop.size*1.7,drop.size);bloodDummy.updateMatrix();bloodSpray.setMatrixAt(i,bloodDummy.matrix);});bloodSpray.count=bloodDrops.length;bloodSpray.instanceMatrix.needsUpdate=true;
 }
 function material(color,glass){const key=color+':'+glass;if(!cache.has(key))cache.set(key,new THREE.MeshStandardMaterial({color,roughness:glass?.15:.9,metalness:glass?.15:0,transparent:glass,opacity:glass?.72:1}));return cache.get(key);}
 function dropBit(){const b=bits.shift();if(b){scene.remove(b.mesh);physics.releaseParticle(b.body);}}
 function burst(pos,color,count=12,power=5,glass=false,kind='chip'){count=Math.min(25,Math.round(count*settings.effects));if(!count||!settings.debris)return;const mat=material(color,glass);for(let i=0;i<count;i++){while(bits.length>=settings.debris)dropBit();const mesh=new THREE.Mesh(glass?shard:kind==='wood'||kind==='metal'?cube:sphere,mat),s=kind==='blood'?.025+Math.random()*.035:.04+Math.random()*.11;mesh.scale.set(glass?s*1.8:kind==='wood'?s*.5:s,glass?s*.12:kind==='wood'?s*3.8:s,s*.7);mesh.position.copy(pos).add(new THREE.Vector3((Math.random()-.5)*.6,Math.random()*.4,(Math.random()-.5)*.6));mesh.castShadow=settings.shadows;scene.add(mesh);const velocity=new THREE.Vector3((Math.random()-.5)*power,Math.random()*power*.6+1,(Math.random()-.5)*power),body=physics.particle(mesh,velocity,glass,kind);bits.push({mesh,body,previous:mesh.position.clone(),falling:false,life:kind==='blood'?.7+Math.random()*.5:2+Math.random()*2});}}
 function blood(pos,splat=false,fallHeight=0){
  const severity=splat?Math.min(3,Math.max(1,fallHeight/14.4)):0,count=Math.round((splat?80+severity*24:8)*Math.max(splat?.4:0,settings.effects));
  for(let i=0;i<Math.min(180,count);i++){if(bloodDrops.length===256)bloodDrops.shift();const angle=Math.random()*Math.PI*2,speed=(splat?3+Math.random()*7:Math.random()*2.5)*(splat?Math.sqrt(severity):1);bloodDrops.push({position:pos.clone(),velocity:new THREE.Vector3(Math.cos(angle)*speed,splat?1+Math.random()*4:1+Math.random()*2,Math.sin(angle)*speed),size:(splat?.045:.025)+Math.random()*.045,floor:support(pos.x,pos.z,pos.y),life:2});}
  const y=support(pos.x,pos.z,pos.y);if(pos.y-y>2.2)return;
  if(!splat){stain(pos.x,y,pos.z,.6+Math.random()*.4);return;}
  const size=4.8+severity*1.4;stain(pos.x,y,pos.z,size,size*.85,Math.random()*Math.PI*2,0);
  for(let i=0;i<5;i++){const angle=Math.random()*Math.PI*2,r=Math.random()*size*.22;stain(pos.x+Math.cos(angle)*r,y,pos.z+Math.sin(angle)*r,size*(.4+Math.random()*.35),size*.45,angle,(i+1)%4);}
  for(let i=0;i<32;i++){const angle=Math.random()*Math.PI*2,r=size*(.2+Math.random()*.55),x=pos.x+Math.cos(angle)*r,z=pos.z+Math.sin(angle)*r,height=support(x,z,y,.05);if(Math.abs(height-y)>.2)continue;const width=.12+Math.random()*.45;stain(x,height,z,width,width*(.5+Math.random()),angle);}
 }
 function shock(pos){if(settings.effects<.3||dust.length>8)return;const mesh=new THREE.Mesh(dustGeo,new THREE.MeshBasicMaterial({color:0xa69b88,transparent:true,opacity:.12,depthWrite:false}));mesh.position.copy(pos);mesh.scale.set(.5,.2,.5);scene.add(mesh);dust.push({mesh,life:.55});}
 function trail(a,b,color=0xa9b6b9){if(trails.length>20||settings.effects<.3)return;const mesh=new THREE.Line(new THREE.BufferGeometry().setFromPoints([a,b]),new THREE.LineBasicMaterial({color,transparent:true,opacity:.5}));scene.add(mesh);trails.push({mesh,life:.1});}
 function update(dt){updateBlood(dt);while(bits.length>Math.min(300,settings.debris))dropBit();for(const b of bits){b.previous.set(b.body.position.x,b.body.position.y,b.body.position.z);b.falling=b.body.velocity.y<0;}physics.step(dt);for(let i=bits.length-1;i>=0;i--){const b=bits[i];b.life-=dt;b.mesh.position.copy(b.body.position);b.mesh.quaternion.copy(b.body.quaternion);if(b.falling)for(const t of getTrampolines())if(bounceContact(b.previous,b.mesh.position,t,b.mesh.scale.y/2)){b.body.position.y=t.y+b.mesh.scale.y/2+.01;b.body.velocity.y=15;b.body.wakeUp();break;}if(b.life<.5)b.mesh.scale.multiplyScalar(1-dt*3);if(b.life<=0){scene.remove(b.mesh);physics.releaseParticle(b.body);bits.splice(i,1);}}
 for(let i=trails.length-1;i>=0;i--){const t=trails[i];t.life-=dt;if(t.life<=0){scene.remove(t.mesh);t.mesh.geometry.dispose();t.mesh.material.dispose();trails.splice(i,1);}}for(let i=dust.length-1;i>=0;i--){const p=dust[i];p.life-=dt;p.mesh.scale.addScalar(dt*2);p.mesh.position.y+=dt*.4;p.mesh.material.opacity=Math.max(0,p.life/.55*.12);if(p.life<=0){scene.remove(p.mesh);p.mesh.material.dispose();dust.splice(i,1);}}
 }
 function clear({keepBlood=false}={}){bloodDrops.length=0;bloodSpray.count=0;if(!keepBlood){for(const batch of stainBatches.values()){scene.remove(batch.mesh);batch.mesh.dispose();}stainBatches.clear();stainCount=0;}while(bits.length)dropBit();physics.clear();for(const t of trails){scene.remove(t.mesh);t.mesh.geometry.dispose();t.mesh.material.dispose();}trails.length=0;for(const p of dust){scene.remove(p.mesh);p.mesh.material.dispose();}dust.length=0;}
 return {burst,blood,ragdoll:physics.ragdoll,removeRagdoll:physics.removeRagdoll,shock,trail,update,clear,get counts(){return {debris:bits.length,bloodStains:stainCount,bloodParticles:bloodDrops.length,ragdolls:physics.counts.ragdolls};}};
}
